    int count = 0;
    for (char digit : x) {
        if (digit == '4' || digit == '7') {
            ++count;
        }
    }

    bool lucky = count > 0;
    while (count > 0) {
        int digit = count % 10;
        if (digit != 4 && digit != 7) {
            lucky = false;
            break;
        }
        count /= 10;
    }

    cout << (lucky ? "YES" : "NO");
    return 0;
}

